{"implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]
    n = len(nodes)
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    result_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            result_edges.append([u, v, w])
            total_weight += w
            if len(result_edges) == n - 1:
                break
    if len(result_edges) != n - 1:
        return {"error": "disconnected input", "edges": [], "total_weight": 0.0}
    return {"edges": result_edges, "total_weight": total_weight}"}
